class FreightCalcCharacterizationTest {

    private static final int TPL = 1032;
    private static final String PROVINCE = "新疆";

    private final FreightCalc calc = new FreightCalc();

    private static Req req(double weight, boolean vip, boolean cod) {
        Req r = new Req();
        r.tplId = TPL;
        r.province = PROVINCE;
        r.weight = weight;
        r.vip = vip;
        r.cod = cod;
        return r;
    }

    // ------------------------------------------------------------------
