    @Test
    @DisplayName("锚点：模板1032 / 新疆 / 3.2kg / 非VIP / 非COD = 33")
    void realRequest() {
        // 18 首重
        //  + ceil(3.2 - 1.0) = 3 段 × 4 = 12
        //  + 3 区域加价
        //  + 0 COD
        assertEquals(33, calc.calc(req(3.2, false, false)));
    }

