        @Test
        @DisplayName("1.0kg 正好不进续重 = 21")
        void exactlyOne() {
            // weight > 1.0 为 false，整段续重跳过：18 + 3
            assertEquals(21, calc.calc(req(1.0, false, false)));
        }

        @Test
        @DisplayName("1.5kg 收 1 段续重 = 25（注释说 0.5kg 进位，代码按 1kg）")
        void oneAndHalf() {
            // ceil(0.5) = 1 段 -> 18 + 4 + 3
