        }

        @Test
        @DisplayName("2.0kg 和 1.5kg 同价 = 25（同一个 1kg 桶的右端点）")
        void exactlyTwo() {
            // ceil(1.0) = 1 段 -> 18 + 4 + 3
            assertEquals(25, calc.calc(req(2.0, false, false)));
        }

        @Test
        @DisplayName("3.0kg 收 2 段 = 29，比 3.2kg 少一段")
        void exactlyThree() {
